export function compose(middlewares) {
    return function run(ctx, next) {
        // index 是「已经进入过的最深层数」，用来发现同一层被 next 两次
        let index = -1;
        function dispatch(current) {
            if (current <= index) {
                return Promise.reject(new Error('next() called multiple times'));
            }
            index = current;
            const middleware = current === middlewares.length ? next : middlewares[current];
            if (!middleware)
                return Promise.resolve();
            try {
                return Promise.resolve(middleware(ctx, () => dispatch(current + 1)));
            }
            catch (error) {
                return Promise.reject(error);
            }
        }
        return dispatch(0);
    };
}

