  leaseSize: number;
  /** 批发失败后隔多久才再问一次，默认 100ms */
  retryAfterMs?: number;
}

export interface LeasedLimiter {
  allow(): boolean;
  /** 本地还剩多少批发来的额度 */
  localBalance(): number;
}

