// 本文件的类型契约（TypeScript 写法，供参考）：
//
// export interface WindowOptions {
//   limit: number;
//   windowMs: number;
// }
//
// export interface Limiter {
//   allow(): boolean;
//   size(): number;
// }

import { now } from '@lab/env';
export function createFixedWindow(options) {
    let windowId = -1;
    let used = 0;
    return {
        allow() {
            // 按时间戳算窗口编号，不用定时器：定时器和请求处理是两条
            // 独立的时间线，而且会让每个实例泄漏一个永不结束的 timer
            const current = Math.floor(now() / options.windowMs);
            if (current !== windowId) {
                windowId = current;
                used = 0;
            }
            if (used >= options.limit)
                return false;
            used += 1;
            return true;
        },
        size() {
            return 2;
        },
    };
}
export function createSlidingLog(options) {
    const stamps = [];
    function prune(at) {
        const cutoff = at - options.windowMs;
        while (stamps.length > 0 && stamps[0] <= cutoff)
            stamps.shift();
    }
    return {
        allow() {
            const at = now();
            // 清理放在最前面，被拒绝的请求也会走到这里。
            // 只在放行路径上清理的话，持续被限流的客户端会让数组永远堆着
            prune(at);
            if (stamps.length >= options.limit)
                return false;
            stamps.push(at);
            return true;
        },
        size() {
            prune(now());
            return stamps.length;
        },
    };
}
export function createSlidingCounter(options) {
    let windowId = -1;
    let current = 0;
    let previous = 0;
    function roll(at) {
        const id = Math.floor(at / options.windowMs);
        if (id === windowId)
            return;
        // 只跨了一个窗口时上一个窗口还有参考价值，跨得更远就全清零
        previous = id === windowId + 1 ? current : 0;
        current = 0;
        windowId = id;
    }
    return {
        allow() {
            const at = now();
            roll(at);
            const elapsed = (at % options.windowMs) / options.windowMs;
            // 权重是「上一个窗口还有多少没滑出去」，即 1 - 已过去的比例。
            // 写成 elapsed 会让行为完全颠倒
            const estimated = previous * (1 - elapsed) + current;
            if (estimated >= options.limit)
                return false;
            current += 1;
            return true;
        },
        size() {
            return 3;
        },
    };
}

