// 本文件的类型契约（TypeScript 写法，供参考）：
//
// export interface SharedStore {
//   /** 从全局配额里取走至多 amount 个，返回实际拿到多少 */
//   take(key: string, amount: number): number;
//   /** 被调用了多少次，用来衡量协调开销 */
//   calls(): number;
//   remaining(key: string): number;
// }

export function createSharedStore(options) {
    const balances = new Map();
    let callCount = 0;
    function balanceOf(key) {
        return balances.has(key) ? balances.get(key) : options.limit;
    }
    return {
        take(key, amount) {
            callCount += 1;
            const left = balanceOf(key);
            const granted = Math.max(0, Math.min(amount, left));
            balances.set(key, left - granted);
            return granted;
        },
        calls() {
            return callCount;
        },
        remaining(key) {
            return balanceOf(key);
        },
    };
}

