// 本文件的类型契约（TypeScript 写法，供参考）：
//
// export interface RetryBudgetOptions {
//   ratio: number;
//   minPerWindow?: number;
//   windowMs: number;
// }
//
// export interface RetryBudget {
//   recordRequest(): void;
//   canRetry(): boolean;
//   recordRetry(): void;
//   usedRatio(): number;
// }

import { now } from '@lab/env';
export function createRetryBudget(options) {
    const minPerWindow = options.minPerWindow ?? 0;
    let windowId = -1;
    let requests = 0;
    let retries = 0;
    function roll() {
        const current = Math.floor(now() / options.windowMs);
        if (current === windowId)
            return;
        windowId = current;
        requests = 0;
        retries = 0;
    }
    function allowance() {
        // minPerWindow 那一项是给低流量兜底的：2 × 0.1 向下取整是 0，
        // 而每秒两个请求恰恰是重试最安全的时候
        return Math.max(minPerWindow, Math.floor(requests * options.ratio));
    }
    return {
        recordRequest() {
            roll();
            // 只记原始请求。把重试也算进来，分母会自我供养：
            // 重试越多，允许的重试越多
            requests += 1;
        },
        canRetry() {
            roll();
            return retries < allowance();
        },
        recordRetry() {
            roll();
            retries += 1;
        },
        usedRatio() {
            roll();
            return requests === 0 ? 0 : retries / requests;
        },
    };
}

