// 本文件的类型契约（TypeScript 写法，供参考）：
//
// export interface ShadowOptions {
//   ratio: number;
// }
//
// export interface ShadowStats {
//   primary: number;
//   shadowed: number;
//   canaryFailures: number;
// }
//
// export interface Shadower {
//   run(
//     key: string,
//     primary: () => Promise<unknown>,
//     canary: () => Promise<unknown>
//   ): Promise<unknown>;
//   stats(): ShadowStats;
// }

function hash(text) {
    let value = 2166136261;
    for (let index = 0; index < text.length; index += 1) {
        value ^= text.charCodeAt(index);
        value = Math.imul(value, 16777619);
    }
    return value >>> 0;
}
export function createShadower(options) {
    const counters = { primary: 0, shadowed: 0, canaryFailures: 0 };
    function shouldShadow(key) {
        if (options.ratio <= 0)
            return false;
        if (options.ratio >= 1)
            return true;
        // 按 key 哈希而不是 Math.random：同一个 key 每次结果一致，
        // 才谈得上「比较同一个请求在新旧版本上的表现」
        return hash(key) % 1000 < options.ratio * 1000;
    }
    return {
        run(key, primary, canary) {
            counters.primary += 1;
            if (shouldShadow(key)) {
                counters.shadowed += 1;
                // fire-and-forget：发出去就不管。await 它的话，
                // 主路径的延迟会变成两者的最大值
                Promise.resolve()
                    .then(canary)
                    .then(() => undefined, () => {
                    // 两个回调都要给。只给 then 不给 reject 处理，
                    // canary 的异常会变成 unhandled rejection，
                    // 某些配置下直接让进程退出——一个只用来观察的旁路杀掉了生产
                    counters.canaryFailures += 1;
                });
            }
            // 主路径原样返回，包括它自己的异常
            return primary();
        },
        stats() {
            return { ...counters };
        },
    };
}

