// 本文件的类型契约（TypeScript 写法，供参考）：
//
// export interface CacheOptions {
//   ttlMs?: number;
//   maxSize?: number;
// }
//
// export interface Cache<T> {
//   get(key: string): T | undefined;
//   set(key: string, value: T): void;
//   readonly size: number;
// }
//
// interface Entry<T> {
//   value: T;
//   expiresAt: number;
// }

import { now } from '@lab/env';
export function createCache(options = {}) {
    const entries = new Map();
    const ttl = options.ttlMs ?? Number.POSITIVE_INFINITY;
    const maxSize = options.maxSize ?? Number.POSITIVE_INFINITY;
    return {
        get(key) {
            const entry = entries.get(key);
            if (!entry)
                return undefined;
            if (entry.expiresAt <= now()) {
                entries.delete(key);
                return undefined;
            }
            // Map 保持插入顺序，删掉再塞回去就是「移到最近使用」
            entries.delete(key);
            entries.set(key, entry);
            return entry.value;
        },
        set(key, value) {
            if (entries.has(key))
                entries.delete(key);
            entries.set(key, { value, expiresAt: now() + ttl });
            while (entries.size > maxSize) {
                const oldest = entries.keys().next().value;
                if (oldest === undefined)
                    break;
                entries.delete(oldest);
            }
        },
        get size() {
            return entries.size;
        },
    };
}
export function createSingleFlight() {
    const inFlight = new Map();
    return function run(key, loader) {
        const existing = inFlight.get(key);
        if (existing)
            return existing;
        const promise = loader().finally(() => {
            inFlight.delete(key);
        });
        inFlight.set(key, promise);
        return promise;
    };
}

import { request } from '@lab/net';
import { mapWithConcurrency } from './pool';
import { withRetry } from './retry';
import { createCache, createSingleFlight } from './cache';
const RETRYABLE_STATUS = [408, 429, 500, 502, 503, 504];
const cache = createCache({ ttlMs: 1000, maxSize: 200 });
const singleFlight = createSingleFlight();
function isRetryable(error) {
    const status = error.status;
    return status === undefined || RETRYABLE_STATUS.indexOf(status) !== -1;
}
async function loadPage(url, options) {
    const run = () => request(url);
    try {
        const response = options.retries
            ? await withRetry(run, {
                retries: options.retries,
                baseDelayMs: options.baseDelayMs ?? 50,
                isRetryable,
            })
            : await run();
        return { url, ok: true, data: response.data };
    }
    catch (error) {
        return { url, ok: false, data: null, error: error.message };
    }
}
export async function fetchPage(url, options = {}) {
    if (!options.ttlMs)
        return loadPage(url, options);
    const cached = cache.get(url);
    if (cached)
        return cached;
    return singleFlight(url, async () => {
        const result = await loadPage(url, options);
        if (result.ok)
            cache.set(url, result);
        return result;
    });
}
export async function fetchAll(urls, options = {}) {
    const concurrency = options.concurrency && options.concurrency > 0 ? options.concurrency : 1;
    return mapWithConcurrency(urls, concurrency, (url) => fetchPage(url, options));
}

