// 本文件的类型契约（TypeScript 写法，供参考）：
//
// export interface Histogram {
//   observe(value: number): void;
//   count(): number;
//   sum(): number;
//   quantile(q: number): number;
//   size(): number;
// }
//
// export interface SpanRecord {
//   name: string;
//   durationMs: number;
// }
//
// export interface Tracer {
//   span(name: string): { end(): void };
//   spans(): SpanRecord[];
//   slowest(): SpanRecord | null;
// }

import { now } from '@lab/env';
export function createHistogram(boundaries) {
    const bounds = boundaries.slice().sort((left, right) => left - right);
    // 桶数固定：观测多少次都只是往这几个计数器上加，
    // 内存与观测数无关。存全量样本才是那个会把进程撑爆的实现
    const counts = [];
    for (let index = 0; index <= bounds.length; index += 1)
        counts.push(0);
    let total = 0;
    let totalSum = 0;
    function bucketFor(value) {
        for (let index = 0; index < bounds.length; index += 1) {
            if (value <= bounds[index])
                return index;
        }
        // 超出所有边界的进 +Inf 桶
        return bounds.length;
    }
    return {
        observe(value) {
            counts[bucketFor(value)] += 1;
            total += 1;
            totalSum += value;
        },
        count() {
            return total;
        },
        sum() {
            return totalSum;
        },
        quantile(q) {
            if (total === 0)
                return 0;
            const last = bounds.length > 0 ? bounds[bounds.length - 1] : 0;
            const target = q * total;
            let cumulative = 0;
            for (let index = 0; index < counts.length; index += 1) {
                const next = cumulative + counts[index];
                if (next < target) {
                    cumulative = next;
                    continue;
                }
                if (counts[index] === 0)
                    return last;
                // +Inf 桶没有上边界，插不了值，只能退回最后一个有限边界
                if (index === bounds.length)
                    return last;
                const lower = index === 0 ? 0 : bounds[index - 1];
                const upper = bounds[index];
                // 桶内线性插值：直接返回 upper 的话，
                // 同一个桶里的 p10 和 p90 会是同一个数
                const withinBucket = (target - cumulative) / counts[index];
                return lower + (upper - lower) * Math.min(1, Math.max(0, withinBucket));
            }
            return last;
        },
        size() {
            return counts.length;
        },
    };
}
export function createTracer() {
    const records = [];
    return {
        span(name) {
            // 起止时刻都存在这个闭包里，并行的 span 各有各的一份，不会互相覆盖
            const startedAt = now();
            let ended = false;
            return {
                end() {
                    // 结束两次不该记两条
                    if (ended)
                        return;
                    ended = true;
                    records.push({ name, durationMs: now() - startedAt });
                },
            };
        },
        spans() {
            return records.slice();
        },
        slowest() {
            if (records.length === 0)
                return null;
            return records.reduce((best, current) => current.durationMs > best.durationMs ? current : best);
        },
    };
}

